[{"id": "call_e878syhq", "function": {"index": 0, "name": "write_file", "arguments": {"path": "config_reader.py", "content": "def read_settings(text):
    """Read settings from text in key=value format."""
    settings = {}

    for line in text.splitlines():
        # Strip surrounding whitespace
        stripped = line.strip()

        # Skip blank lines and comment lines
        if not stripped or stripped.startswith('#'):
            continue

        # Split on first '=' only
        if '=' not in stripped:
            raise ValueError("Malformed line: missing '='")

        key, value = stripped.split('=', 1)
        key = key.strip()
        value = value.strip()

        # Check for duplicate keys
        if key in settings:
            raise ValueError(f"Duplicate key: {key}")

        # Validate that value is not empty
        if not value:
            raise ValueError(f"Malformed line: empty value for key '{key}'")

        settings[key] = value

    # Check for required keys
    if 'endpoint' not in settings:
        raise ValueError("Missing required key: endpoint")

    if 'enabled' not in settings:
        raise ValueError("Missing required key: enabled")

    # Parse enabled as boolean (true/false, case-insensitive)
    enabled_value = settings['enabled'].lower()
    if enabled_value not in ('true', 'false'):
        raise ValueError(f"Invalid value for 'enabled': {settings['enabled']}")

    return {'endpoint': settings['endpoint'], 'enabled': enabled_value == 'true'}
